/** ACP v1 stdio adapter backed by the fixed official Java SDK. */
public final class AcpV1Server implements AutoCloseable {
    private final SessionApplicationService sessions;
    private final PermissionBroker permissions;
    private final PromptApplicationService prompts;
    private final AcpAsyncAgent agent;

    public AcpV1Server(InputStream input, OutputStream output, SessionApplicationService sessions,
                       PermissionBroker permissions, PromptApplicationService prompts, ModelRef defaultModel) {
        this.sessions = sessions;
        this.permissions = permissions;
        this.prompts = prompts;
        var transport = new StdioAcpAgentTransport(AcpJsonMapper.createDefault(), input, output);
        agent = AcpAgent.async(transport)
                .initializeHandler(request -> Mono.just(
                        AcpSchema.InitializeResponse.ok(new AcpSchema.AgentCapabilities(true, null, null))))
                .newSessionHandler(request -> Mono.fromSupplier(() -> new AcpSchema.NewSessionResponse(
                        sessions.create(defaultModel, request.cwd()).id(), null, null)))
                .loadSessionHandler(request -> Mono.fromSupplier(() -> {
                    sessions.load(request.sessionId());
                    return new AcpSchema.LoadSessionResponse(null, null);
                }))
                .promptHandler(this::prompt)
                .cancelHandler(request -> Mono.fromRunnable(() -> sessions.cancel(request.sessionId())))
                .build();
    }

    public void run() {
        agent.start().then(agent.awaitTermination()).block();
    }

    private Mono<AcpSchema.PromptResponse> prompt(AcpSchema.PromptRequest request, PromptContext context) {
        var subscriber = new AcpSubscriber(request.sessionId(), context, permissions);
        sessions.events(request.sessionId()).subscribe(subscriber);
        String commandId = request.meta().get("commandId") instanceof String value ? value
                : "acp-" + java.util.UUID.randomUUID();
        PromptApplicationService.Acceptance accepted = prompts.prompt(request.sessionId(), commandId, request.text());
        AgentRun run = accepted.run().orElseThrow(() -> new IllegalStateException("ACP prompt command was already accepted"));
        return Mono.fromFuture(run.completion().toCompletableFuture())
                .map(result -> result.outcome() == AgentEvent.Outcome.ABORTED
                        ? new AcpSchema.PromptResponse(AcpSchema.StopReason.CANCELLED)
                        : AcpSchema.PromptResponse.endTurn())
                .doFinally(ignored -> subscriber.close());
    }

    @Override
    public void close() {
        agent.closeGracefully().block();
    }

    private static final class AcpSubscriber implements Flow.Subscriber<AgentEvent>, AutoCloseable {
        private final String sessionId;
        private final PromptContext context;
        private final PermissionBroker permissions;
        private Flow.Subscription subscription;
        private String streamedText = "";
        AcpSubscriber(String sessionId, PromptContext context, PermissionBroker permissions) {
            this.sessionId = sessionId;
            this.context = context;
            this.permissions = permissions;
        }
        @Override public void onSubscribe(Flow.Subscription value) { subscription = value; value.request(Long.MAX_VALUE); }
        @Override public void onNext(AgentEvent event) {
            if (event instanceof AgentEvent.TextStreamed streamed) {
                String delta = streamed.accumulatedText().startsWith(streamedText)
                        ? streamed.accumulatedText().substring(streamedText.length())
                        : streamed.accumulatedText();
                streamedText = streamed.accumulatedText();
                send(context.sendUpdate(sessionId, new AcpSchema.AgentMessageChunk(
                        "agent_message_chunk", new AcpSchema.TextContent(delta), streamed.messageId())));
            } else if (event instanceof AgentEvent.ToolChanged tool) {
                send(context.sendUpdate(sessionId, new AcpSchema.ToolCall(
                        "tool_call", tool.toolCallId(), tool.toolName(), AcpSchema.ToolKind.OTHER, map(tool.status()),
                        List.of(), List.of(), tool.arguments(), tool.result(), java.util.Map.of())));
            } else if (event instanceof AgentEvent.PermissionChanged permission
                    && permission.status() == AgentEvent.PermissionStatus.PENDING) {
                requestPermission(permission);
            } else if (event instanceof AgentEvent.UsageChanged usage) {
                send(context.sendUpdate(sessionId,
                        new AcpSchema.UsageUpdate("usage_update", usage.usage().totalTokens(), 0L)));
            }
        }
        private void requestPermission(AgentEvent.PermissionChanged permission) {
            context.requestPermission(new AcpSchema.RequestPermissionRequest(sessionId,
                            new AcpSchema.ToolCallUpdate(permission.request().toolCallId(), permission.request().toolName(),

